import assert from 'node:assert/strict';
import { test } from 'node:test';
import { entryScss, entryTsx, optionsTs } from '../../../src/drafts/domain/entry.ts';
import { layoutIssues, parseLayout } from '../../../src/drafts/domain/layout.ts';
import { briefTemplate, layoutTemplate } from '../../../src/drafts/domain/templates.ts';

const SECTIONS = [{ id: 'hero' }, { id: 'order-summary' }];

test('index.tsx imports every section and passes the state', () => {
  assert.equal(
    entryTsx(SECTIONS),
    [
      '// Generated by kitvas from md/layout.md. Do not edit: change the layout and run "kitvas layout".',
      "import { Hero } from './sections/Hero.tsx';",
      "import { OrderSummary } from './sections/OrderSummary.tsx';",
      '',
      'export type DraftProps = { state: string };',
      '',
      'export function Draft({ state }: DraftProps) {',
      '  return (',
      '    <>',
      '      <Hero state={state} />',
      '      <OrderSummary state={state} />',
      '    </>',
      '  );',
      '}',
      '',
    ].join('\n'),
  );
});

const OPTIONS = [
  {
    id: 'columns',
    label: 'Columns',
    default: '3',
    values: [
      { id: '3', label: 'Three' },
      { id: '2', label: 'Two' },
    ],
  },
  {
    id: 'card-style',
    label: 'Cards',
    default: 'outlined',
    values: [
      { id: 'outlined', label: 'Outlined' },
      { id: 'filled', label: 'Filled' },
    ],
  },
];

test('no options give the same entry as before, byte for byte', () => {
  assert.equal(entryTsx(SECTIONS, []), entryTsx(SECTIONS));
});

test('options add the type and the prop of Draft, and every section gets the props whole', () => {
  const text = entryTsx(SECTIONS, OPTIONS);
  assert.ok(text.includes("import type { Options } from './options.ts';"));
  assert.ok(text.includes('export type DraftProps = { state: string; options: Options };'));
  assert.ok(text.includes('export function Draft(props: DraftProps) {'));
  // A spread, not a named `options`: a section that reads no option keeps `{ state: string }`
  // and still passes the type check, so a new option touches only the sections that use it.
  assert.ok(text.includes('      <Hero {...props} />'));
  assert.ok(text.includes('      <OrderSummary {...props} />'));
  assert.ok(!text.includes('options={options}'));
});

test('the Options type has the exact values of each option, written through JSON.stringify', () => {
  assert.equal(
    optionsTs(OPTIONS),
    [
      '// Generated by kitvas from src/json/options.json. Do not edit: change the options and run "kitvas layout".',
      'export type Options = { "columns": "3" | "2"; "card-style": "outlined" | "filled" };',
      '',
    ].join('\n'),
  );
  const odd = optionsTs([
    { id: 'a', label: 'A', default: 'x', values: [{ id: 'x"y', label: 'X' }] },
  ]);
  assert.ok(odd.includes('"x\\"y"'));
});

test('index.scss uses every section sheet', () => {
  assert.equal(
    entryScss(SECTIONS),
    [
      '// Generated by kitvas from md/layout.md. Do not edit: change the layout and run "kitvas layout".',
      "@use 'sections/hero';",
      "@use 'sections/order-summary';",
      '',
    ].join('\n'),
  );
});

test('the scaffolds carry the title; a fresh layout has no sections yet', () => {
  assert.match(briefTemplate('Rent a bike'), /^# Brief: Rent a bike\n/);
  assert.match(briefTemplate('Rent a bike'), /^## Goal$/m);
  const layout = parseLayout(layoutTemplate('Rent a bike'));
  assert.equal(layout.title, 'Rent a bike');
  assert.match(layoutTemplate('Rent a bike'), /^## shared$/m);
  assert.equal(layout.shared, '');
  assert.deepEqual(
    layoutIssues(layout, new Set()).map((issue) => issue.key),
    ['draftIssue.noSections'],
  );
});
